class FlakyPurger(ArtifactPurger):  # pylint: disable=too-few-public-methods
    """Fail its first delete attempt, then enforce the real exact-file purge."""

    def __init__(self, staging_root: Path):
        super().__init__(staging_root)
        self.calls = 0

    def purge(self, artifact: ArtifactRef) -> bool:
        """Inject one transient filesystem error for retry regressions."""

        self.calls += 1
        if self.calls == 1:
            raise PurgeError(
                PurgeFailureCode.FILESYSTEM_ERROR,
                "simulated interruption before deletion: SENSITIVE_PURGE_PATH_SENTINEL",
            )
        return super().purge(artifact)
